    // ---- terminal ----
    const winTex = windowTexture();
    this.winTex = winTex;
    const term = new THREE.Group();
    const body = new THREE.Mesh(new THREE.BoxGeometry(320, 22, 46),
      new THREE.MeshStandardMaterial({ color: 0xcfd6dd, roughness: 0.5, metalness: 0.15 }));
