function buildAirliner() {
  const grp = new THREE.Group();
  const parts = {};
  const white = fuselageMat(0xf4f6f8);
  const accent = fuselageMat(0x0f9d58);
  const wingMat = new THREE.MeshStandardMaterial({ color: 0xdfe5ea, roughness: 0.34, metalness: 0.5 });

  const fus = new THREE.Mesh(new THREE.CylinderGeometry(2.0, 1.7, 30, 18), white);
  fus.rotation.x = Math.PI / 2;
  const nose = new THREE.Mesh(new THREE.SphereGeometry(2.0, 18, 12), white);
  nose.scale.set(1, 1, 2.4); nose.position.z = 15;
  const tailCone = new THREE.Mesh(new THREE.ConeGeometry(1.7, 6.5, 14), white);
  tailCone.rotation.x = -Math.PI / 2; tailCone.position.z = -18.2;
  grp.add(fus, nose, tailCone);

  const winTex = windowStripTexture();
  winTex.repeat.set(10, 1);
  const winMat = new THREE.MeshStandardMaterial({
    color: 0x18263a, roughness: 0.15, metalness: 0.8,
    emissive: 0xffdf9e, emissiveMap: winTex, emissiveIntensity: 0,
  });
  const winStrip = new THREE.Mesh(new THREE.CylinderGeometry(2.02, 2.02, 26, 18, 1, true), winMat);
  winStrip.rotation.x = Math.PI / 2;
  grp.add(winStrip);
  parts.windowMat = winMat;

  const cockpit = new THREE.Mesh(new THREE.BoxGeometry(2.4, 1.0, 1.9), matGlass());
  cockpit.position.set(0, 1.2, 15.6);
  grp.add(cockpit);

  // faixa da livery
  const stripe = new THREE.Mesh(new THREE.CylinderGeometry(2.03, 1.72, 30, 18, 1, true),
    new THREE.MeshStandardMaterial({ color: 0x0f9d58, roughness: 0.35, metalness: 0.5, side: THREE.DoubleSide }));
  stripe.rotation.x = Math.PI / 2;
  stripe.scale.y = 0.06;   // anel fino? — não; use posição
  grp.remove(stripe);

  // asas enflechadas com diedro
  for (const s of [-1, 1]) {
    const w = new THREE.Mesh(new THREE.BoxGeometry(16.5, 0.55, 4.6), wingMat);
    w.position.set(s * 8.6, -1.1, -1.2);
    w.rotation.y = -s * 0.5;
    w.rotation.z = s * 0.09;
    grp.add(w);
    const tip = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.4, 2.2), accent);
    tip.position.set(s * 16.4, -0.2, -4.9);
    tip.rotation.y = -s * 0.5;
    grp.add(tip);
  }
  parts.flapL = surface(6.5, 1.6, 0.22, accent); parts.flapL.position.set(-5.0, -1.05, -3.2); parts.flapL.rotation.y = 0.5;
  parts.flapR = surface(6.5, 1.6, 0.22, accent); parts.flapR.position.set(5.0, -1.05, -3.2); parts.flapR.rotation.y = -0.5;
  parts.ailL = surface(5.0, 1.2, 0.18, accent); parts.ailL.position.set(-12.0, -0.62, -5.6); parts.ailL.rotation.y = 0.5;
  parts.ailR = surface(5.0, 1.2, 0.18, accent); parts.ailR.position.set(12.0, -0.62, -5.6); parts.ailR.rotation.y = -0.5;
  grp.add(parts.flapL, parts.flapR, parts.ailL, parts.ailR);

  // motores sob as asas
  parts.fans = [];
  for (const s of [-1, 1]) {
    const nacG = new THREE.Group();
    const nac = new THREE.Mesh(new THREE.CylinderGeometry(1.55, 1.35, 4.6, 16), matMetal());
    nac.rotation.x = Math.PI / 2;
    const lip = new THREE.Mesh(new THREE.TorusGeometry(1.55, 0.16, 8, 16), matDark());
    lip.position.z = -2.3;
    const fan = new THREE.Group();
    for (let b = 0; b < 12; b++) {
      const bl = new THREE.Mesh(new THREE.BoxGeometry(0.2, 1.3, 0.05), matDark());
      bl.rotation.z = (b / 12) * TAU;
      bl.position.set(Math.sin((b / 12) * TAU) * 0.66, Math.cos((b / 12) * TAU) * 0.66, 0);
      fan.add(bl);
    }
    fan.position.z = -2.1;
    nacG.add(nac, lip, fan);
    nacG.position.set(s * 6.4, -2.6, -0.6);
    nacG.rotation.y = s * 0.06;
    grp.add(nacG);
    parts.fans.push(fan);
  }

  // empenagem
  const fin = new THREE.Mesh(new THREE.BoxGeometry(0.35, 7.4, 5.2), accent);
  fin.position.set(0, 4.6, -16.6);
  const hStab = new THREE.Mesh(new THREE.BoxGeometry(13.5, 0.4, 3.4), wingMat);
  hStab.position.set(0, 1.6, -17.6);
  grp.add(fin, hStab);
  parts.elev = surface(13.0, 1.4, 0.2, accent); parts.elev.position.set(0, 1.6, -19.35);
  parts.rudder = new THREE.Group();
  const rud = new THREE.Mesh(new THREE.BoxGeometry(0.3, 6.2, 2.0), accent);
  rud.position.set(0, 0, 1.05);
  parts.rudder.add(rud);
  parts.rudder.position.set(0, 4.4, -17.5);
  grp.add(parts.elev, parts.rudder);

  // trem de pouso alto
  parts.gear = new THREE.Group();
  const mkLeg = (x, z, len, wheelR, wheelW, wheels = 1) => {
    const lg = new THREE.Group();
    const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, len, 8), matMetal());
    leg.position.y = -len / 2;
    lg.add(leg);
    const wh = [];
    for (let i = 0; i < wheels; i++) {
      const wheel = makeWheel(wheelR, wheelW);
      wheel.position.set(i % 2 === 0 ? 0.42 * wheelR : -0.42 * wheelR, -len, 0);
      lg.add(wheel); wh.push(wheel);
    }
    lg.position.set(x, 0, z);
    lg.userData.wheels = wh;
    return lg;
  };
  parts.gearN = mkLeg(0, 12.4, 2.4, 0.5, 0.3);
  parts.gearM = new THREE.Group();
  const mL = mkLeg(-3.1, -1.4, 2.7, 0.62, 0.4, 2);
  const mR = mkLeg(3.1, -1.4, 2.7, 0.62, 0.4, 2);
  parts.gearM.add(mL, mR);
  parts.gear.add(parts.gearN, parts.gearM);
  grp.add(parts.gear);
  parts.wheels = [...parts.gearN.userData.wheels, ...mL.userData.wheels, ...mR.userData.wheels];

  // spoilers
  parts.spoilers = [];
  for (const s of [-1, 1]) {
    for (let i = 0; i < 2; i++) {
      const sp = new THREE.Group();
      const panel = new THREE.Mesh(new THREE.BoxGeometry(3.2, 0.14, 1.1), accent);
      panel.position.z = 0.55;
      sp.add(panel);
      sp.position.set(s * (6 + i * 4), -0.75, -2.4);
      grp.add(sp);
      parts.spoilers.push(sp);
    }
  }

  // luzes
  parts.navL = new THREE.Mesh(new THREE.SphereGeometry(0.14, 6, 4), new THREE.MeshBasicMaterial({ color: 0xff2020 }));
  parts.navL.position.set(-16.8, -0.15, -4.6);
  parts.navR = new THREE.Mesh(new THREE.SphereGeometry(0.14, 6, 4), new THREE.MeshBasicMaterial({ color: 0x20ff40 }));
  parts.navR.position.set(16.8, -0.15, -4.6);
  parts.beacon = new THREE.Mesh(new THREE.SphereGeometry(0.13, 6, 4), new THREE.MeshBasicMaterial({ color: 0xff2020 }));
  parts.beacon.position.set(0, 2.15, 2);
  parts.strobeL = new THREE.Mesh(new THREE.SphereGeometry(0.12, 6, 4), new THREE.MeshBasicMaterial({ color: 0xffffff }));
  parts.strobeL.position.copy(parts.navL.position);
  parts.strobeR = parts.strobeL.clone(); parts.strobeR.position.copy(parts.navR.position);
  grp.add(parts.navL, parts.navR, parts.beacon, parts.strobeL, parts.strobeR);

  grp.traverse(o => { if (o.isMesh) o.castShadow = true; });
  return { grp, parts };
}

// ---------------------------------------------------------------------------
// COCKPIT (painel funcional compartilhado)
// ---------------------------------------------------------------------------
export function buildCockpit(spec, instruments) {
  const g = new THREE.Group();
  const [cx, cy, cz] = spec.cam.cockpit;
  const panelW = spec.key === 'airliner' ? 3.4 : 1.7;
  const panelY = cy - 0.32;

  const dash = new THREE.Mesh(new THREE.BoxGeometry(panelW, 0.5, 0.5), matDark());
  dash.position.set(cx, panelY + 0.12, cz + 0.62);
  const shade = new THREE.Mesh(new THREE.BoxGeometry(panelW + 0.2, 0.5, 0.4), matDark());
  shade.position.set(cx, panelY + 0.42, cz + 0.45);
  shade.rotation.x = -0.9;
  g.add(dash, shade);

  const gaugeMeshes = [];
  const gw = panelW * 0.2;
  const order = [instruments.asi, instruments.att, instruments.alt];
  for (let i = 0; i < 3; i++) {
    const m = new THREE.Mesh(
      new THREE.PlaneGeometry(gw, gw),
      new THREE.MeshBasicMaterial({ map: order[i].texture, toneMapped: false })
    );
    m.position.set(cx + (i - 1) * gw * 1.15, panelY + 0.22, cz + 0.36);
    m.rotation.x = -0.12;
    g.add(m);
    gaugeMeshes.push(m);
  }

  // manche / sidestick
  const yoke = new THREE.Group();
  const column = new THREE.Mesh(new THREE.CylinderGeometry(0.035, 0.035, 0.5, 8), matDark());
  column.position.y = -0.25;
  const wheel = new THREE.Mesh(new THREE.TorusGeometry(0.16, 0.028, 8, 16), matDark());
  wheel.rotation.x = Math.PI / 2;
  yoke.add(column, wheel);
  yoke.position.set(cx + (panelW > 2 ? -panelW * 0.32 : 0), panelY - 0.05, cz + 0.2);
  g.add(yoke);

  // manetes
  const thrG = new THREE.Group();
  for (let i = 0; i < (spec.engine.count > 1 ? 2 : 1); i++) {
    const t = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.03, 0.3, 6), matMetal());
    t.position.set(i * 0.09 - 0.045, 0, 0);
    t.rotation.x = -0.8;
    thrG.add(t);
  }
  thrG.position.set(cx + panelW * 0.32, panelY - 0.02, cz + 0.3);
  g.add(thrG);

  // luz interna noturna
  const light = new THREE.PointLight(0xffd9a0, 0, 6, 2);
  light.position.set(cx, panelY + 0.9, cz + 0.1);
  g.add(light);

  return { group: g, yoke, throttle: thrG, light };
}

// ---------------------------------------------------------------------------
export function buildAircraft(key) {
  const spec = SPECS[key];
  let built;
  if (key === 'cessna') built = buildCessna();
  else if (key === 'jet') built = buildJet();
  else built = buildAirliner();
  return { group: built.grp, parts: built.parts, spec };
}

// ============================================================================
// physics.js — Modelo aerodinâmico baseado em forças:
// sustentação (CL x ângulo de ataque), arrasto, empuxo, gravidade,
// densidade do ar, estol, vento cruzado, turbulência, dinâmica rotacional
// (arfagem/rolagem/guinada), solo com freios/esteering e consumo.
// ============================================================================
import * as THREE from 'three';

const G = 9.81;
const D2R = Math.PI / 180;
const R2D = 180 / Math.PI;
const MS2KT = 1.94384;
const FT = 3.28084;

export class FlightModel {
  constructor(spec) {
    this.spec = spec;
    this.pos = new THREE.Vector3();
    this.vel = new THREE.Vector3();
    this.quat = new THREE.Quaternion();
    this.angVel = new THREE.Vector3();     // taxas no corpo (rad/s): x=arf, y=gui, z=rol
    this.accWorld = new THREE.Vector3();   // para efeitos visuais

    this.throttle = 0;
    this.rpm = 0;                          // 0..1 (spool)
    this.temp = 20;
    this.fuel = spec.fuelCap;
    this.flapsIdx = 0;
    this.gearDown = true;
    this.gearPos = 1;                      // 1=abaixado, 0=recolhido
    this.spoilers = false;
    this.brakes = 0;
    this.reverse = false;
    this.engineOn = true;

    this.onGround = true;
    this.crashed = false;
    this.crashReason = '';
    this.stalled = false;
    this.overheat = false;
    this.gLoad = 1;
    this.touchedDown = false;
    this.lastTouchVS = 0;

    // vetores reutilizados
    this._fwd = new THREE.Vector3();
    this._up = new THREE.Vector3();
    this._right = new THREE.Vector3();
    this._airVel = new THREE.Vector3();
    this._vb = new THREE.Vector3();
    this._force = new THREE.Vector3();
    this._tmp = new THREE.Vector3();
    this._tmp2 = new THREE.Vector3();
    this._q2 = new THREE.Quaternion();
    this._eul = new THREE.Euler();
    this._wind = new THREE.Vector3();
    this.alpha = 0; this.beta = 0; this.qbar = 0;
  }

  reset(spawn, headingDeg, speed, altitude) {
    const spec = this.spec;
    this.pos.copy(spawn);
    this.quat.setFromEuler(new THREE.Euler(0, -headingDeg * D2R, 0, 'YXZ'));
    // velocidade inicial ao longo do nariz
    this._fwd.set(0, 0, 1).applyQuaternion(this.quat);
    this.vel.copy(this._fwd).multiplyScalar(speed);
    if (altitude > 0) this.vel.y = 0;
    this.angVel.set(0, 0, 0);
    this.throttle = 0; this.rpm = 0; this.temp = 20;
    this.fuel = spec.fuelCap;
    this.flapsIdx = 0;
    this.gearDown = altitude === 0;
    this.gearPos = this.gearDown ? 1 : 0;
    this.spoilers = false; this.brakes = 0; this.reverse = false;
    this.onGround = altitude === 0;
    this.crashed = false; this.crashReason = '';
    this.stalled = false; this.touchedDown = false;
    this.gLoad = 1;
    if (altitude > 0) { this.throttle = 0.7; this.rpm = 0.7; }
  }

  get mass() { return this.spec.mass + this.fuel; }

  step(dt, input, env, groundH, t) {
    if (this.crashed) return;
    const spec = this.spec;

    // -------------------- sistemas --------------------
    // acelerador com resposta progressiva (spool)
    this.throttle = THREE.MathUtils.clamp(input.throttle, 0, 1);
    const spoolT = spec.engine.spool;
    const rpmTarget = this.throttle;
    this.rpm += (rpmTarget - this.rpm) * Math.min(1, dt / spoolT);

    // temperatura do motor
    const tempTarget = 20 + this.rpm * (this.throttle > 0.9 ? 118 : 96);
    this.temp += (tempTarget - this.temp) * Math.min(1, dt * 0.05);
    this.overheat = this.temp > 108;
    const thrustEff = this.overheat ? 0.65 : 1;

    // combustível
    if (this.fuel > 0) {
      this.fuel = Math.max(0, this.fuel - this.throttle * spec.fuelBurn * dt);
    }
    this.engineOn = this.fuel > 0;

    // trem de pouso (animação 2.2 s)
    this.gearDown = input.gearDown;
    const gSpeed = spec.gear.retractable ? 1 / 2.2 : 99;
    this.gearPos = THREE.MathUtils.clamp(this.gearPos + (this.gearDown ? gSpeed : -gSpeed) * dt, 0, 1);

    this.flapsIdx = THREE.MathUtils.clamp(input.flapsIdx, 0, spec.flaps.length - 1);
    this.spoilers = input.spoilers && spec.hasSpoiler;
    this.brakes = input.brakes;
    this.reverse = input.reverse && spec.hasReverse;

    // -------------------- ar -------------------- 
    const rho = THREE.MathUtils.max(env.airDensity(this.pos.y), 0.0001);
    env.getWind(this._wind, t);
    this._airVel.copy(this.vel).sub(this._wind);
    const V = this._airVel.length();

    this._fwd.set(0, 0, 1).applyQuaternion(this.quat);
    this._up.set(0, 1, 0).applyQuaternion(this.quat);
    this._right.set(1, 0, 0).applyQuaternion(this.quat);

    // velocidade do ar no referencial do corpo
    this._q2.copy(this.quat).invert();
    this._vb.copy(this._airVel).applyQuaternion(this._q2);
    this.alpha = V > 2 ? Math.atan2(-this._vb.y, Math.max(0.001, this._vb.z)) : 0;
    this.beta = V > 2 ? Math.atan2(this._vb.x, Math.max(0.001, this._vb.z)) : 0;
    this.qbar = 0.5 * rho * V * V;

    // -------------------- coeficientes --------------------
    const flap = spec.flaps[this.flapsIdx];
    const aStall = spec.alphaStall * D2R - this.flapsIdx * 1.2 * D2R;
    let CL = spec.CL0 + spec.CLa * this.alpha + flap.cl;
    const aDeg = this.alpha * R2D;
    this.stalled = false;
    if (this.alpha > aStall) {
      // estol: perda progressiva de sustentação
      const over = (this.alpha - aStall) / D2R;
      const clMax = CL;
      CL = Math.max(clMax * (1 - over / 9), 0.35);
      this.stalled = over > 0.6;
    } else if (this.alpha < -0.14) {
      // alpha negativo extremo
      CL = Math.max(CL, -0.6);
    }
    if (this.spoilers) CL *= 0.62;

    let CD = spec.CD0 + spec.kInd * CL * CL + flap.cd
      + spec.gear.drag * this.gearPos
      + (this.spoilers ? 0.06 : 0)
      + (Math.abs(this.beta) > 0.12 ? 0.02 * Math.abs(this.beta) * 10 : 0);
    // arrasto compressivo
    const mach = V / 320;
    if (mach > 0.75) CD += (mach - 0.75) * 0.25;

    const S = spec.S;
    const qbarS = this.qbar * S;

    // -------------------- forças --------------------
    this._force.set(0, -this.mass * G, 0);

    // empuxo
    let thrust = 0;
    if (this.engineOn) {
      const rhoFac = rho / 1.225;
      if (spec.engine.type === 'prop') {
        const fade = THREE.MathUtils.clamp(V / (spec.vne * 1.6), 0, 1);
        thrust = spec.engine.maxThrust * this.rpm * (1 - spec.engine.thrustFade * fade) * rhoFac;
      } else {
        thrust = spec.engine.maxThrust * this.rpm * rhoFac * (0.35 + 0.65 * Math.min(1, this.rpm + 0.15));
      }
      thrust *= thrustEff;
      if (this.reverse && this.onGround) thrust = -Math.abs(thrust) * 0.45;
      this._tmp.copy(this._fwd).multiplyScalar(thrust / (spec.engine.count || 1) * (spec.engine.count || 1));
      this._force.add(this._tmp);
    }

    // sustentação (perpendicular ao vento relativo)
    if (V > 1) {
      const airDir = this._tmp.copy(this._airVel).normalize();
      // direção de sustentação: up projetado perpendicular ao vento relativo
      const liftDir = this._tmp2.copy(this._up).addScaledVector(airDir, -this._up.dot(airDir)).normalize();
      this._force.addScaledVector(liftDir, qbarS * CL);
      // arrasto
      this._force.addScaledVector(airDir, -qbarS * CD);
      // força lateral (derrapagem)
      const sideDir = this._tmp.copy(this._right).addScaledVector(airDir, -this._right.dot(airDir)).normalize();
      this._force.addScaledVector(sideDir, -qbarS * 1.1 * this.beta);
    }

    this.gLoad = this.qbarS * CL / (this.mass * G) * Math.cos(this.beta) || 0;

    // turbulência (acelerações aleatórias proporcionais ao clima)
    if (env.cfg.turb > 0 && !this.onGround) {
      const tb = env.cfg.turb * Math.min(1, 0.4 + V / 80);
      const tn = (s) => Math.sin(t * s * 1.7 + this.pos.x * 0.001 + this.pos.y * 0.0007) * Math.sin(t * s * 0.53);
      this._force.x += tn(1.1) * tb * this.mass * 1.1;
      this._force.y += tn(0.9) * tb * this.mass * 1.5;
      this._force.z += tn(1.3) * tb * this.mass * 1.1;
    }

    // -------------------- integração linear --------------------
    this.accWorld.copy(this._force).divideScalar(this.mass);
    this.vel.addScaledVector(this.accWorld, dt);
    this.pos.addScaledVector(this.vel, dt);

    // -------------------- dinâmica rotacional --------------------
    const qfac = this.qbar / (this.qbar + spec.qRef);
    const stallEff = THREE.MathUtils.clamp(1 - (Math.abs(this.alpha) - aStall * 0.85) / (aStall * 0.8), 0.25, 1);
    let ax = 0, ay = 0, az = 0;

    const elev = THREE.MathUtils.clamp(input.pitch, -1, 1);
    const ail = THREE.MathUtils.clamp(input.roll, -1, 1);
    const rud = THREE.MathUtils.clamp(input.yaw, -1, 1);

    if (!this.onGround) {
      // arfagem: comando + estabilidade estática + amortecimento
      ax += -elev * spec.pitchPow * qfac * stallEff;
      ax += spec.pitchStab * (this.alpha - 2.0 * D2R) * qfac * stallEff;
      ax -= spec.pitchDamp * this.angVel.x * qfac;

      // rolagem: ailerons + efeito de guinada + amortecimento
      az += -ail * spec.rollPow * qfac * stallEff;
      az -= spec.rollDamp * this.angVel.z * qfac;
      az += -this.beta * 1.2 * qfac;             // diedro

      // guinada: leme + vertical de cauda (weathervane) + amortecimento
      ay += -rud * spec.yawPow * qfac * stallEff;
      ay += spec.yawStab * this.beta * qfac;
      ay -= spec.yawDamp * this.angVel.y * qfac;

      // buffeting no estol
      if (this.stalled) {
        const b = 2.2 * (1 - Math.min(1, Math.abs(this.alpha - aStall) / (8 * D2R)));
        ax += (Math.random() - 0.5) * b;
        az += (Math.random() - 0.5) * b * 2.4;
      }
      // turbulência rotacional
      if (env.cfg.turb > 0) {
        const tb = env.cfg.turb * 0.5;
        ax += Math.sin(t * 2.3 + 5) * tb * 0.4;
        az += Math.sin(t * 3.1 + 2) * tb * 0.8;
        ay += Math.sin(t * 1.7 + 9) * tb * 0.3;
      }
    } else {
      // -------------------- SOLO --------------------
      // direção: leme no solo (trem de nariz)
      const vh = Math.hypot(this.vel.x, this.vel.z);
      const steerF = THREE.MathUtils.clamp(1 - vh / 60, 0.12, 1);
      ay += -rud * spec.gear.steer * steerF * (vh > 0.5 ? 1 : 0);
      ay -= this.angVel.y * 8;
      az += -this.angVel.z * 10;   // rolagem travada no solo
      // arfagem no solo: só rotação pelo profundor
      ax += -elev * spec.pitchPow * qfac * (vh > spec.vRotate * 0.55 ? 1 : 0.15);
      ax -= this.angVel.x * 14;
    }

    this.angVel.x += ax * dt;
    this.angVel.y += ay * dt;
    this.angVel.z += az * dt;
    const maxRate = 3.2;
    this.angVel.x = THREE.MathUtils.clamp(this.angVel.x, -maxRate, maxRate);
    this.angVel.y = THREE.MathUtils.clamp(this.angVel.y, -maxRate, maxRate);
    this.angVel.z = THREE.MathUtils.clamp(this.angVel.z, -maxRate, maxRate);

    // integra quaternion (taxas no referencial do corpo)
    const w = this.angVel;
    const halfDt = dt * 0.5;
    const dq = new THREE.Quaternion(
      w.x * halfDt, w.y * halfDt, w.z * halfDt, 0
    );
    dq.multiply(this.quat);
    this.quat.x += dq.x; this.quat.y += dq.y; this.quat.z += dq.z; this.quat.w += dq.w;
    this.quat.normalize();

    // -------------------- SOLO / COLISÃO --------------------
    const gh = groundH(this.pos.x, this.pos.z);
    const gearY = spec.gear.height * (0.25 + 0.75 * this.gearPos);
    const contactY = gh + gearY;
    const wasGround = this.onGround;
    this.onGround = false;

    if (this.pos.y <= contactY + 0.05) {
      const vv = this.vel.y;
      const pitchE = Math.asin(THREE.MathUtils.clamp(this._fwd.y, -1, 1)) * R2D;
      const rollE = Math.atan2(this._right.y, Math.hypot(this._right.x, this._right.z)) * R2D;
      const vh = Math.hypot(this.vel.x, this.vel.z);

      const gearOK = this.gearPos > 0.92;
      const hardVS = vv < -7.5 - (spec.key === 'cessna' ? 1.5 : 0);
      const badAtt = Math.abs(rollE) > 14 || pitchE < -6 || pitchE > 17;
      const onRunway = Math.abs(this.pos.x) < 1330 && Math.abs(this.pos.z) < 320;
      const grassHard = !onRunway && vh > 42;

      if (!wasGround || vv < -0.5) this.lastTouchVS = vv;

      if (hardVS || (badAtt && vh > 15) || (!gearOK && vh > 12) || grassHard) {
        this.crashed = true;
        this.crashReason =
          hardVS ? `Impacto excessivo — ${Math.abs(vv * FT * 60).toFixed(0)} ft/min no toque` :
          (!gearOK && vh > 12) ? 'Pouso com trem recolhido' :
          (badAtt ? `Atitude incorreta no contato (roll ${rollE.toFixed(0)}°, pitch ${pitchE.toFixed(0)}°)` :
                    'Pouso fora do aeroporto em alta velocidade');
        return;
      }

      // ---- contato válido ----
      this.onGround = true;
      this.pos.y = contactY;
      this.touchedDown = true;
      if (!wasGround) this.lastTouchVS = vv;

      // mola de solo simples
      this.vel.y = Math.max(0, this.vel.y * -0.15);

      // atrito de rolagem + freios + reverso
      const decel = (onRunway ? 0.55 : 1.6) + this.brakes * (onRunway ? 4.6 : 2.6)
        + (this.reverse && this.engineOn ? 2.4 : 0);
      if (vh > 0.01) {
        const f = Math.max(0, vh - decel * dt) / vh;
        this.vel.x *= f; this.vel.z *= f;
      }

      // atrito lateral dos pneus (impede derrapar de lado)
      const fwdH = this._tmp.set(this._fwd.x, 0, this._fwd.z).normalize();
      const rightH = this._tmp2.set(fwdH.z, 0, -fwdH.x).negate();
      const vAlong = this.vel.x * fwdH.x + this.vel.z * fwdH.z;
      let vSide = this.vel.x * rightH.x + this.vel.z * rightH.z;
      vSide *= Math.exp(-dt * 7);
      this.vel.x = fwdH.x * vAlong + rightH.x * vSide;
      this.vel.z = fwdH.z * vAlong + rightH.z * vSide;

      // atitude no solo: nivelar asas, pitch >= repouso
      this._eul.setFromQuaternion(this.quat, 'YXZ');
      this._eul.z += (0 - this._eul.z) * Math.min(1, dt * 10);
      const restPitch = spec.restPitch;
      if (this._eul.x < restPitch) this._eul.x += (restPitch - this._eul.x) * Math.min(1, dt * 6);
      this._eul.x = Math.min(this._eul.x, 15 * D2R);
      this.quat.setFromEuler(this._eul);
      if (this._eul.x > restPitch + 0.02 && vh < 3) {
        // cauda apoiada em taxi lento: volta ao repouso
        this._eul.x += (restPitch - this._eul.x) * Math.min(1, dt * 2);
      }
    }

    // teto estrutural
    if (this.pos.y > 14000) { this.pos.y = 14000; this.vel.y = Math.min(0, this.vel.y); }
  }

  // -------------------- dados derivados para HUD --------------------
  data(env) {
    const V = this.vel.length();
    const ias = V * Math.sqrt(THREE.MathUtils.max(env.airDensity(this.pos.y), 0) / 1.225) * MS2KT;
    const gs = V * MS2KT;
    const hdg = (Math.atan2(this._fwd.x, this._fwd.z) * R2D + 360) % 360;
    const gh = 0; // preenchido pelo main quando necessário
    return {
      iasKt: ias, gsKt: gs,
      altFt: this.pos.y * FT,
      vsFpm: this.vel.y * FT * 60,
      hdg,
      mach: V / 320,
      gLoad: this.gLoad,
      alphaDeg: this.alpha * R2D,
      stallSpeedKt: this._stallSpeedKt(env),
    };
  }
  _stallSpeedKt(env) {
    const flap = this.spec.flaps[this.flapsIdx];
    const clMax = this.spec.CL0 + this.spec.CLa * this.spec.alphaStall * D2R + flap.cl;
    const rho = THREE.MathUtils.max(env.airDensity(this.pos.y), 0.0001);
    const v = Math.sqrt(2 * this.mass * G / (rho * this.spec.S * clMax));
    return v * MS2KT;
  }
}

// ============================================================================
// audio.js — Áudio sintetizado (WebAudio): motor a pistão, turbofan,
// vento, chuva, alarme de estol, trovão. Posicional (pan/volume por câmera).
// ============================================================================
export class SoundSystem {
  constructor() {
    this.enabled = true;
    this.ready = false;
    this.ctx = null;
  }

  init() {
    if (this.ready) return;
    try {
      this.ctx = new (window.AudioContext || window.webkitAudioContext)();
      const ctx = this.ctx;

      this.master = ctx.createGain();
      this.master.gain.value = 0.8;
      this.master.connect(ctx.destination);

      // -------- motor --------
      this.engGain = ctx.createGain(); this.engGain.gain.value = 0;
      this.engPan = ctx.createStereoPanner();
      this.engGain.connect(this.engPan).connect(this.master);

      if (true) { // criado por tipo no setEngineType
        this.osc1 = ctx.createOscillator(); this.osc1.type = 'sawtooth';
        this.osc2 = ctx.createOscillator(); this.osc2.type = 'square';
        this.engFilter = ctx.createBiquadFilter(); this.engFilter.type = 'lowpass';
        const g1 = ctx.createGain(); g1.gain.value = 0.5;
        const g2 = ctx.createGain(); g2.gain.value = 0.22;
        this.osc1.connect(g1).connect(this.engFilter);
        this.osc2.connect(g2).connect(this.engFilter);
        this.engFilter.connect(this.engGain);
        this.osc1.start(); this.osc2.start();
      }

      // -------- jato (ruído filtrado + apito) --------
      const noiseBuf = ctx.createBuffer(1, ctx.sampleRate * 2, ctx.sampleRate);
      const nd = noiseBuf.getChannelData(0);
      for (let i = 0; i < nd.length; i++) nd[i] = Math.random() * 2 - 1;
      this.noiseBuf = noiseBuf;

      this.jetSrc = ctx.createBufferSource();
      this.jetSrc.buffer = noiseBuf; this.jetSrc.loop = true;
      this.jetFilter = ctx.createBiquadFilter(); this.jetFilter.type = 'bandpass';
      this.jetFilter.Q.value = 0.7;
      this.whine = ctx.createOscillator(); this.whine.type = 'sine'; this.whine.frequency.value = 2000;
      this.whineGain = ctx.createGain(); this.whineGain.gain.value = 0;
      this.jetGain = ctx.createGain(); this.jetGain.gain.value = 0;
      this.jetPan = ctx.createStereoPanner();
      this.jetSrc.connect(this.jetFilter).connect(this.jetGain);
      this.whine.connect(this.whineGain).connect(this.jetGain);
      this.jetGain.connect(this.jetPan).connect(this.master);
      this.jetSrc.start(); this.whine.start();

      // -------- vento --------
      this.windSrc = ctx.createBufferSource();
      this.windSrc.buffer = noiseBuf; this.windSrc.loop = true;
      this.windFilter = ctx.createBiquadFilter(); this.windFilter.type = 'lowpass';
      this.windFilter.frequency.value = 400;
      this.windGain = ctx.createGain(); this.windGain.gain.value = 0;
      this.windSrc.connect(this.windFilter).connect(this.windGain).connect(this.master);
      this.windSrc.start();

      // -------- chuva --------
      this.rainSrc = ctx.createBufferSource();
      this.rainSrc.buffer = noiseBuf; this.rainSrc.loop = true;
      this.rainFilter = ctx.createBiquadFilter(); this.rainFilter.type = 'highpass';
      this.rainFilter.frequency.value = 2500;
      this.rainGain = ctx.createGain(); this.rainGain.gain.value = 0;
      this.rainSrc.connect(this.rainFilter).connect(this.rainGain).connect(this.master);
      this.rainSrc.start();

      // -------- alarme de estol --------
      this.alarmGain = ctx.createGain(); this.alarmGain.gain.value = 0;
      this.alarmGain.connect(this.master);
      this.alarmOsc = null;
      this._alarmPhase = 0;

      this.ready = true;
    } catch (e) {
      console.warn('Audio indisponível', e);
    }
  }

  setEnabled(v) {
    this.enabled = v;
    if (this.ready) this.master.gain.value = v ? 0.8 : 0;
  }

  resume() { if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume(); }

  update(dt, st) {
    // st: {type, rpm, throttle, airspeedMS, rainAmt, stall, onGround, camDist, pan, cockpit, thunder}
    if (!this.ready) return;
    const T = this.ctx.currentTime;

    let distAtt = st.cockpit ? 1 : THREE_att(st.camDist);
    function THREE_att(d) { return 1 / (1 + d / 40); }

    // alarme de estol: bip intermitente
    if (st.stall) {
      this._alarmPhase += dt * 3.4;
      const on = (this._alarmPhase % 1) < 0.5;
      if (on && !this.alarmOsc) {
        this.alarmOsc = this.ctx.createOscillator();
        this.alarmOsc.type = 'square';
        this.alarmOsc.frequency.value = 880;
        this.alarmOsc.connect(this.alarmGain);
        this.alarmOsc.start();
      } else if (!on && this.alarmOsc) {
        this.alarmOsc.stop(); this.alarmOsc = null;
      }
      this.alarmGain.gain.setTargetAtTime(on ? 0.06 * distAtt : 0, T, 0.02);
    } else {
      if (this.alarmOsc) { this.alarmOsc.stop(); this.alarmOsc = null; }
      this.alarmGain.gain.setTargetAtTime(0, T, 0.05);
    }

    const r = st.rpm;
    if (st.type === 'prop') {
      const f = 38 + r * 74;
      this.osc1.frequency.setTargetAtTime(f, T, 0.05);
      this.osc2.frequency.setTargetAtTime(f * 0.503, T, 0.05);
      this.engFilter.frequency.setTargetAtTime(180 + r * 900, T, 0.05);
      this.engGain.gain.setTargetAtTime((0.05 + r * 0.22) * distAtt, T, 0.06);
      this.jetGain.gain.setTargetAtTime(0, T, 0.1);
      this.whineGain.gain.setTargetAtTime(0, T, 0.1);
    } else {
      this.jetFilter.frequency.setTargetAtTime(220 + r * 1500, T, 0.08);
      this.whine.frequency.setTargetAtTime(1400 + r * 3200, T, 0.08);
      this.whineGain.gain.setTargetAtTime((0.015 + r * 0.045) * distAtt, T, 0.08);
      this.jetGain.gain.setTargetAtTime((0.04 + r * 0.3) * distAtt, T, 0.08);
      this.engGain.gain.setTargetAtTime(0, T, 0.1);
    }

    const air = st.airspeedMS;
    this.windGain.gain.setTargetAtTime(Math.min(0.4, Math.pow(air / 120, 2) * 0.5) * (st.cockpit ? 1 : 0.7), T, 0.1);
    this.windFilter.frequency.setTargetAtTime(250 + air * 9, T, 0.1);

    this.rainGain.gain.setTargetAtTime(st.rainAmt * 0.12 * (st.cockpit ? 0.6 : 1), T, 0.4);

    // pan pela posição relativa da aeronave à câmera
    const pan = THREE.MathUtils.clamp(st.pan, -1, 1);
    this.engPan.pan.setTargetAtTime(st.cockpit ? 0 : pan, T, 0.1);
    this.jetPan.pan.setTargetAtTime(st.cockpit ? 0 : pan, T, 0.1);
  }

  thunder() {
    if (!this.ready) return;
    const ctx = this.ctx, T = ctx.currentTime;
    const src = ctx.createBufferSource();
    src.buffer = this.noiseBuf; src.loop = true;
    const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 120;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.0, T);
    g.gain.linearRampToValueAtTime(0.55, T + 0.08);
    g.gain.exponentialRampToValueAtTime(0.001, T + 2.8);
    src.connect(f).connect(g).connect(this.master);
    src.start(); src.stop(T + 3);
  }

  click() {
    if (!this.ready) return;
    const ctx = this.ctx, T = ctx.currentTime;
    const o = ctx.createOscillator(); o.type = 'sine'; o.frequency.value = 700;
    const g = ctx.createGain();
    g.gain.setValueAtTime(0.08, T);
    g.gain.exponentialRampToValueAtTime(0.001, T + 0.09);
    o.connect(g).connect(this.master);
    o.start(); o.stop(T + 0.1);
  }
}

// ============================================================================
// controls.js — Entrada: joystick virtual (toque), slider de acelerador,
// botões físicos, teclado e inclinação do dispositivo.
// ============================================================================
export class InputSystem {
  constructor() {
    this.pitch = 0;     // -1 nariz para baixo .. +1 puxar
    this.roll = 0;      // -1 esq .. +1 dir
    this.yaw = 0;       // -1 esq .. +1 dir
    this.throttle = 0;
    this.brakes = 0;
    this.gearDown = true;
    this.flapsIdx = 0;
    this.spoilers = false;
    this.reverse = false;

    this._keys = {};
    this._tiltOn = false;
    this._tiltPitch = 0;
    this._tiltRoll = 0;
    this._joyId = null;
    this._thrId = null;
    this._rudId = null;
    this.onCamera = null;
    this.onPause = null;
    this.onTiltToggle = null;
    this.onSoundToggle = null;
  }

  bind({ joyZone, joyStick, thrSlider, thrFill, thrHandle,
    btnGear, btnFlaps, btnSpr, btnRvs, btnBrk, btnRudL, btnRudR,
    btnCam, btnPause, btnTilt, btnSound }, cb) {

    this.onCamera = cb.camera; this.onPause = cb.pause;
    this.onTiltToggle = cb.tilt; this.onSoundToggle = cb.sound;

    // ---------------- joystick ----------------
    const stick = joyStick;
    const baseR = () => joyZone.querySelector('#joyBase').clientWidth / 2 - 26;
    let jx = 0, jy = 0;
    const setStick = () => {
      stick.style.transform = `translate(calc(-50% + ${jx}px), calc(-50% + ${jy}px))`;
    };
    const joyMove = (e) => {
      const r = joyZone.getBoundingClientRect();
      const bx = r.left + 24 + 62, by = r.bottom - 26 - 62;  // centro aproximado da base
      const base = joyZone.querySelector('#joyBase');
      const br = base.getBoundingClientRect();
      const cx = br.left + br.width / 2, cy = br.top + br.height / 2;
      let dx = e.clientX - cx, dy = e.clientY - cy;
      const max = br.width / 2 - 10;
      const d = Math.hypot(dx, dy);
      if (d > max) { dx *= max / d; dy *= max / d; }
      jx = dx; jy = dy; setStick();
      this.roll = dx / max;
      this.pitch = -dy / max;
    };
    joyZone.addEventListener('pointerdown', (e) => {
      if (this._joyId !== null) return;
      this._joyId = e.pointerId;
      joyZone.setPointerCapture(e.pointerId);
      joyMove(e);
    });
    joyZone.addEventListener('pointermove', (e) => { if (e.pointerId === this._joyId) joyMove(e); });
    const joyEnd = (e) => {
      if (e.pointerId !== this._joyId) return;
      this._joyId = null;
      jx = 0; jy = 0; setStick();
      this.roll = 0; this.pitch = 0;
    };
    joyZone.addEventListener('pointerup', joyEnd);
    joyZone.addEventListener('pointercancel', joyEnd);

    // ---------------- acelerador ----------------
    const thrSet = (e) => {
      const r = thrSlider.getBoundingClientRect();
      const t = 1 - THREE.clamp((e.clientY - r.top) / r.height, 0, 1);
      this.throttle = t;
      const pct = Math.round(t * 100);
      thrFill.style.height = pct + '%';
      thrHandle.style.bottom = `calc(${pct}% - ${(pct / 100) * 34}px)`;
      thrHandle.textContent = pct + '%';
    };
    thrSlider.addEventListener('pointerdown', (e) => {
      if (this._thrId !== null) return;
      this._thrId = e.pointerId;
      thrSlider.setPointerCapture(e.pointerId);
      thrSet(e);
    });
    thrSlider.addEventListener('pointermove', (e) => { if (e.pointerId === this._thrId) thrSet(e); });
    const thrEnd = (e) => { if (e.pointerId === this._thrId) this._thrId = null; };
    thrSlider.addEventListener('pointerup', thrEnd);
    thrSlider.addEventListener('pointercancel', thrEnd);

    // ---------------- botões ----------------
    const press = (el, on, off) => {
      el.addEventListener('pointerdown', (e) => { e.preventDefault(); on(); });
      if (off) {
        el.addEventListener('pointerup', off);
        el.addEventListener('pointercancel', off);
        el.addEventListener('pointerleave', off);
      }
    };
    press(btnGear, () => { this.gearDown = !this.gearDown; cb.click(); cb.syncGear(this.gearDown); });
    press(btnFlaps, () => { this.flapsIdx++; cb.click(); cb.syncFlaps(this.flapsIdx); });
    press(btnSpr, () => { this.spoilers = !this.spoilers; cb.click(); cb.syncSpr(this.spoilers); });
    press(btnRvs, () => { this.reverse = !this.reverse; cb.click(); cb.syncRvs(this.reverse); });
    press(btnBrk, () => { this.brakes = 1; cb.syncBrk(true); }, () => { this.brakes = 0; cb.syncBrk(false); });
    press(btnRudL, () => { this._yawL = true; this._yawUpd(); }, () => { this._yawL = false; this._yawUpd(); });
    press(btnRudR, () => { this._yawR = true; this._yawUpd(); }, () => { this._yawR = false; this._yawUpd(); });

    btnCam.addEventListener('pointerdown', (e) => { e.preventDefault(); this.onCamera && this.onCamera(); });
    btnPause.addEventListener('pointerdown', (e) => { e.preventDefault(); this.onPause && this.onPause(); });
    btnTilt.addEventListener('pointerdown', (e) => { e.preventDefault(); this.onTiltToggle && this.onTiltToggle(); });
    btnSound.addEventListener('pointerdown', (e) => { e.preventDefault(); this.onSoundToggle && this.onSoundToggle(); });

    // ---------------- teclado ----------------
    window.addEventListener('keydown', (e) => {
      if (e.repeat) return;
      this._keys[e.code] = true;
      switch (e.code) {
        case 'KeyG': this.gearDown = !this.gearDown; cb.click(); cb.syncGear(this.gearDown); break;
        case 'KeyF': this.flapsIdx++; cb.click(); cb.syncFlaps(this.flapsIdx); break;
        case 'KeyV': this.spoilers = !this.spoilers; cb.click(); cb.syncSpr(this.spoilers); break;
        case 'KeyR': this.reverse = !this.reverse; cb.click(); cb.syncRvs(this.reverse); break;
        case 'KeyB': this.brakes = 1; cb.syncBrk(true); break;
        case 'KeyC': this.onCamera && this.onCamera(); break;
        case 'KeyP': case 'Escape': this.onPause && this.onPause(); break;
      }
    });
    window.addEventListener('keyup', (e) => {
      this._keys[e.code] = false;
      if (e.code === 'KeyB') { this.brakes = 0; cb.syncBrk(false); }
    });

    window.addEventListener('deviceorientation', (e) => {
      if (!this._tiltOn) return;
      this._tiltRoll = THREE.clamp((e.gamma || 0) / 28, -1, 1);
      this._tiltPitch = THREE.clamp(((e.beta || 0) - 38) / 30, -1, 1);
    });
  }

  _yawUpd() {
    this.yaw = (this._yawL ? -1 : 0) + (this._yawR ? 1 : 0);
  }

  toggleTilt() { this._tiltOn = !this._tiltOn; return this._tiltOn; }
  get tiltOn() { return this._tiltOn; }

  // chamado a cada frame antes da física
  sample(dt) {
    const k = this._keys;
    let kp = (k['ArrowUp'] ? 1 : 0) - (k['ArrowDown'] ? 1 : 0);
    let kr = (k['ArrowRight'] ? 1 : 0) - (k['ArrowLeft'] ? 1 : 0);
    let ky = (k['KeyE'] ? 1 : 0) - (k['KeyQ'] ? 1 : 0);
    const kt = ((k['KeyW'] || k['PageUp'] ? 1 : 0) - (k['KeyS'] || k['PageDown'] ? 1 : 0)) * dt * 0.5;
    if (kt !== 0) {
      this.throttle = THREE.clamp(this.throttle + kt, 0, 1);
      const fill = document.getElementById('thrFill');
      const handle = document.getElementById('thrHandle');
      if (fill) {
        const pct = Math.round(this.throttle * 100);
        fill.style.height = pct + '%';
        handle.style.bottom = `calc(${pct}% - ${(pct / 100) * 34}px)`;
        handle.textContent = pct + '%';
      }
    }
    if (this._tiltOn) {
      // inclinação soma ao joystick
      this.effPitch = THREE.clamp(this.pitch + this._tiltPitch, -1, 1);
      this.effRoll = THREE.clamp(this.roll + this._tiltRoll, -1, 1);
    } else {
      this.effPitch = THREE.clamp(this.pitch + kp, -1, 1);
      this.effRoll = THREE.clamp(this.roll + kr, -1, 1);
    }
    this.effYaw = THREE.clamp(this.yaw + ky, -1, 1);
  }
}

// pequeno helper local (evita importar three aqui)
const THREE = {
  clamp: (v, a, b) => Math.max(a, Math.min(b, v)),
};

// ============================================================================
// hud.js — Interface: velocidade, altitude, direção, combustível, avisos.
// ============================================================================
export class HUD {
  constructor() {
    this.el = {};
    for (const id of ['gSpd', 'gGs', 'gAlt', 'gAgl', 'gHdg', 'gVs', 'sThr', 'bThr', 'sFuel', 'bFuel',
      'sTemp', 'bTemp', 'sFlaps', 'sGear', 'sMach', 'sWind', 'warnings', 'fpsBox', 'camName',
      'touchdownMsg', 'gearSub', 'flapsSub', 'brkSub']) {
      this.el[id] = document.getElementById(id);
    }
    this._warnCache = '';
    this._fpsAcc = 0; this._fpsN = 0;
    this._tdT = 0;
  }

  update(dt, d) {
    // d: dados derivados
    const e = this.el;
    e.gSpd.textContent = Math.round(d.iasKt);
    e.gGs.textContent = 'GS ' + Math.round(d.gsKt);
    e.gAlt.textContent = Math.round(d.altFt).toLocaleString('pt-BR');
    e.gAgl.textContent = 'AGL ' + Math.round(d.aglFt).toLocaleString('pt-BR');
    e.gHdg.textContent = String(Math.round(d.hdg)).padStart(3, '0') + '°';
    const vs = Math.round(d.vsFpm / 50) * 50;
    e.gVs.textContent = 'VS ' + (vs > 0 ? '+' : '') + vs.toLocaleString('pt-BR');
    e.sThr.textContent = Math.round(d.throttle * 100) + '%' + (d.reverse ? ' RVS' : '');
    e.bThr.style.width = (d.throttle * 100) + '%';
    e.sFuel.textContent = Math.round(d.fuelPct) + '%';
    e.bFuel.style.width = d.fuelPct + '%';
    e.sTemp.textContent = Math.round(d.temp) + '°C';
    e.bTemp.style.width = Math.min(100, d.temp) + '%';
    e.sFlaps.textContent = d.flapName;
    e.sGear.textContent = d.gearTxt;
    e.sGear.style.color = d.gearCol;
    e.sMach.textContent = d.mach.toFixed(2);
    e.sWind.textContent = d.windTxt;

    // FPS
    this._fpsAcc += dt; this._fpsN++;
    if (this._fpsAcc >= 0.5) {
      e.fpsBox.textContent = 'FPS ' + Math.round(this._fpsN / this._fpsAcc) + ' · ' + d.quality.toUpperCase();
      this._fpsAcc = 0; this._fpsN = 0;
    }

    // mensagens de toque
    if (d.touchMsg) {
      e.touchdownMsg.textContent = d.touchMsg;
      e.touchdownMsg.style.opacity = 1;
      this._tdT = 3.5;
    } else if (this._tdT > 0) {
      this._tdT -= dt;
      if (this._tdT <= 0) e.touchdownMsg.style.opacity = 0;
    }
  }

  setWarnings(list) {
    // lista de [id, texto, classe]
    const key = JSON.stringify(list);
    if (key === this._warnCache) return;
    this._warnCache = key;
    const w = this.el.warnings;
    w.innerHTML = '';
    for (const [, txt, cls] of list) {
      const div = document.createElement('div');
      div.className = 'warnBox ' + (cls || '');
      div.textContent = txt;
      w.appendChild(div);
    }
  }

  setCam(name) { this.el.camName.textContent = 'CÂMERA: ' + name; }
  setQuality(q) { this._quality = q; }
}

// ============================================================================
// main.js — Real Flight Simulator 3D: integração de todos os sistemas.
// ============================================================================
import * as THREE from 'three';
import { Environment, WEATHERS } from './env.js';
import { World, terrainHeight, WORLD } from './world.js';
import { SPECS, buildAircraft, buildCockpit, CockpitInstruments } from './aircraft.js';
import { FlightModel } from './physics.js';
import { SoundSystem } from './audio.js';
import { InputSystem } from './controls.js';
import { HUD } from './hud.js';

const D2R = Math.PI / 180;
const R2D = 180 / Math.PI;
const MS2KT = 1.94384;
const FT = 3.28084;

window.__errors = [];
window.addEventListener('error', (e) => window.__errors.push(String(e.message || e)));

// ---------------------------------------------------------------------------
const $ = (id) => document.getElementById(id);
const canvas = $('gl');

const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: 'high-performance' });
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.05;
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xb6cfe4, 500, 6000);

const camera = new THREE.PerspectiveCamera(62, innerWidth / innerHeight, 0.3, 15000);

const env = new Environment(scene, 'medium');
const world = new World(scene, env, 'medium');
const sound = new SoundSystem();
env.onLightning = () => sound.thunder();

const hud = new HUD();
const instruments = new CockpitInstruments();
const input = new InputSystem();

// ---------------------------------------------------------------------------
// estado do jogo
// ---------------------------------------------------------------------------
const GAME = {
  started: false,
  paused: false,
  aircraftKey: 'cessna',
  startMode: 'runway',
  quality: 'medium',
  camMode: 0,                       // 0 externa, 1 perseguição, 2 cockpit, 3 lateral
  camNames: ['CÂMERA EXTERNA', 'PERSEGUIÇÃO', 'COCKPIT', 'LATERAL'],
  orbit: { yaw: 2.2, pitch: 0.34, dist: 18 },
  tSim: 0,
  fm: null,
  ac: null,                         // { group, parts, spec }
  cockpit: null,
  touchMsg: '',
  lastAGL: Infinity,
  fps: 0,
};

// ---------------------------------------------------------------------------
// construção da aeronave
// ---------------------------------------------------------------------------
function spawnAircraft(key) {
  if (GAME.ac) {
    scene.remove(GAME.ac.group);
    scene.remove(GAME.cockpit.group);
  }
  const { group, parts, spec } = buildAircraft(key);

  // disco de blur da hélice/fan
  const blurMat = new THREE.MeshBasicMaterial({ color: 0x1a1d22, transparent: true, opacity: 0, depthWrite: false, side: THREE.DoubleSide });
  if (parts.prop) {
    const disc = new THREE.Mesh(new THREE.CircleGeometry(0.98, 18), blurMat);
    parts.prop.add(disc);
    parts.blur = disc;
  }
  if (parts.fans) {
    parts.blurFans = [];
    for (const f of parts.fans) {
      const disc = new THREE.Mesh(new THREE.CircleGeometry(1.45, 18), blurMat.clone());
      parts.blurFans.push(disc);
      f.add(disc);
    }
  }

  // luz de pouso
  const landingLight = new THREE.SpotLight(0xfff2cc, 0, 260, 0.5, 0.5, 1.2);
  landingLight.position.set(0, -0.4, spec.key === 'airliner' ? 16 : 4);
  const llTarget = new THREE.Object3D();
  llTarget.position.set(0, -6, 80);
  group.add(landingLight, llTarget);
  landingLight.target = llTarget;
  parts.landingLight = landingLight;

  scene.add(group);
  const cockpit = buildCockpit(spec, instruments);
  group.add(cockpit.group);
  cockpit.group.visible = false;

  GAME.ac = { group, parts, spec };
  GAME.cockpit = cockpit;
  GAME.fm = new FlightModel(spec);

  // botões não aplicáveis ficam desativados
  $('btnSpr').classList.toggle('off', !spec.hasSpoiler);
  $('btnRvs').classList.toggle('off', !spec.hasReverse);

  GAME.orbit.dist = spec.cam.ext;
  return spec;
}

function spawn() {
  const spec = GAME.ac.spec;
  const fm = GAME.fm;
  if (GAME.startMode === 'runway') {
    const y = terrainHeight(-1250, 0) + spec.gear.height;
    fm.reset(new THREE.Vector3(-1250, y, 0), 90, 0, 0);
    input.flapsIdx = 1;
  } else {
    const y = terrainHeight(0, 0) + spec.gear.height + 300;
    fm.reset(new THREE.Vector3(-600, y, 0), 90, spec.vApproach * 1.9, 1);
    input.flapsIdx = 0;
  }
  input.gearDown = GAME.startMode === 'runway';
  input.throttle = GAME.startMode === 'runway' ? 0 : 0.7;
  input.spoilers = false; input.reverse = false;
  syncButtons();
  GAME.touchMsg = '';
  GAME.lastAGL = Infinity;
  GAME.camMode = 0;
  orbitBehind();
}

function orbitBehind() {
  const hdg = Math.atan2(GAME.ac.group.position.x, 0) * 0; // recalculado abaixo
  const fm = GAME.fm;
  const f = new THREE.Vector3(0, 0, 1).applyQuaternion(fm.quat);
  const hdgRad = Math.atan2(f.x, f.z);
  GAME.orbit.yaw = hdgRad + Math.PI;
  GAME.orbit.pitch = 0.32;
}

// ---------------------------------------------------------------------------
// botões / sincronização de UI
// ---------------------------------------------------------------------------
function syncButtons() {
  const spec = GAME.ac.spec;
  $('btnGear').classList.toggle('active', input.gearDown);
  $('gearSub').textContent = input.gearDown ? 'ABAIXADO' : 'RECOLHIDO';
  const fl = THREE.MathUtils.clamp(input.flapsIdx, 0, spec.flaps.length - 1);
  input.flapsIdx = fl;
  $('flapsSub').textContent = spec.flaps[fl].name;
  $('btnSpr').classList.toggle('active', input.spoilers);
  $('btnRvs').classList.toggle('active', input.reverse);
  $('btnBrk').classList.toggle('active', input.brakes > 0);
}

// ---------------------------------------------------------------------------
// qualidade gráfica
// ---------------------------------------------------------------------------
const QUALITY = {
  low:    { pr: 0.8, shadow: 0, fog: 2800, far: 13000, exposure: 1.0 },
  medium: { pr: 1.3, shadow: 1024, fog: 4500, far: 15000, exposure: 1.05 },
  high:   { pr: 1.8, shadow: 2048, fog: 6500, far: 18000, exposure: 1.05 },
  ultra:  { pr: 2.2, shadow: 4096, fog: 9500, far: 24000, exposure: 1.08 },
};
function applyQuality(q) {
  GAME.quality = q;
  const c = QUALITY[q];
  const dpr = Math.min(window.devicePixelRatio || 1, 2.5);
  renderer.setPixelRatio(Math.min(c.pr, dpr));
  renderer.setSize(innerWidth, innerHeight);
  renderer.shadowMap.enabled = c.shadow > 0;
  env.sun.castShadow = c.shadow > 0;
  if (c.shadow > 0) {
    if (env.sun.shadow.map) { env.sun.shadow.map.dispose(); env.sun.shadow.map = null; }
    env.sun.shadow.mapSize.set(c.shadow, c.shadow);
  }
  env.fogDist = c.fog;
  camera.far = c.far;
  camera.updateProjectionMatrix();
  env.setQuality(q);
  world.setQuality(q);
  hud.setQuality(q);
  document.querySelectorAll('#gfxChips .chip, #gfxChips2 .chip').forEach(ch => {
    ch.classList.toggle('sel', ch.dataset.v === q);
  });
}

// ---------------------------------------------------------------------------
// câmeras
// ---------------------------------------------------------------------------
const _v1 = new THREE.Vector3(), _v2 = new THREE.Vector3(), _v3 = new THREE.Vector3();
const _qFlip = new THREE.Quaternion().setFromAxisAngle(new THREE.Vector3(0, 1, 0), Math.PI);
const _chasePos = new THREE.Vector3();
let _chaseInit = false;

function updateCamera(dt) {
  const { ac, fm } = GAME;
  const pos = ac.group.position;
  const spec = ac.spec;

  if (GAME.camMode === 2) {
    // cockpit
    _v1.fromArray(spec.cam.cockpit);
    ac.group.localToWorld(_v1);
    camera.position.copy(_v1);
    camera.quaternion.copy(fm.quat).multiply(_qFlip);
  } else if (GAME.camMode === 0) {
    // externa orbital
    const o = GAME.orbit;
    _v1.set(
      Math.sin(o.yaw) * Math.cos(o.pitch),
      Math.sin(o.pitch),
      Math.cos(o.yaw) * Math.cos(o.pitch)
    ).multiplyScalar(o.dist).add(pos);
    const gh = terrainHeight(_v1.x, _v1.z) + 1.5;
    if (_v1.y < gh) _v1.y = gh;
    camera.position.copy(_v1);
    camera.lookAt(pos);
  } else if (GAME.camMode === 1) {
    // perseguição suavizada
    _v1.fromArray(spec.cam.chase).applyQuaternion(fm.quat).add(pos);
    if (!_chaseInit) { _chasePos.copy(_v1); _chaseInit = true; }
    _chasePos.lerp(_v1, 1 - Math.exp(-dt * 3.5));
    const gh = terrainHeight(_chasePos.x, _chasePos.z) + 1.5;
    if (_chasePos.y < gh) _chasePos.y = gh;
    camera.position.copy(_chasePos);
    _v2.copy(pos).addScaledVector(_v3.set(0, 0, 1).applyQuaternion(fm.quat), 12);
    camera.lookAt(_v2);
  } else {
    // lateral
    _v1.set(spec.cam.ext * 0.85, 4, 0).applyQuaternion(fm.quat).add(pos);
    const gh = terrainHeight(_v1.x, _v1.z) + 1.5;
    if (_v1.y < gh) _v1.y = gh;
    camera.position.copy(_v1);
    camera.lookAt(pos);
  }
  cockpitVisibility();
}

function cockpitVisibility() {
  const isCockpit = GAME.camMode === 2;
  if (GAME.cockpit) GAME.cockpit.group.visible = isCockpit;
  $('cockpitGlow').style.display = isCockpit ? 'block' : 'none';
}

// ---------------------------------------------------------------------------
// órbita / zoom no canvas
// ---------------------------------------------------------------------------
const pointers = new Map();
let pinchDist = 0;
canvas.addEventListener('pointerdown', (e) => {
  pointers.set(e.pointerId, { x: e.clientX, y: e.clientY });
  if (pointers.size === 2) {
    const [a, b] = [...pointers.values()];
    pinchDist = Math.hypot(a.x - b.x, a.y - b.y);
  }
});
canvas.addEventListener('pointermove', (e) => {
  if (!pointers.has(e.pointerId)) return;
  const p = pointers.get(e.pointerId);
  const dx = e.clientX - p.x, dy = e.clientY - p.y;
  p.x = e.clientX; p.y = e.clientY;
  if (pointers.size === 1 && GAME.camMode === 0) {
    GAME.orbit.yaw -= dx * 0.006;
    GAME.orbit.pitch = THREE.MathUtils.clamp(GAME.orbit.pitch + dy * 0.005, 0.02, 1.45);
  } else if (pointers.size === 2 && GAME.camMode === 0) {
    const [a, b] = [...pointers.values()];
    const d = Math.hypot(a.x - b.x, a.y - b.y);
    GAME.orbit.dist = THREE.MathUtils.clamp(GAME.orbit.dist * (pinchDist / Math.max(1, d)), 8, 600);
    pinchDist = d;
  }
});
const clearPointer = (e) => pointers.delete(e.pointerId);
canvas.addEventListener('pointerup', clearPointer);
canvas.addEventListener('pointercancel', clearPointer);
canvas.addEventListener('wheel', (e) => {
  if (GAME.camMode === 0) {
    GAME.orbit.dist = THREE.MathUtils.clamp(GAME.orbit.dist * (1 + e.deltaY * 0.001), 8, 600);
  }
}, { passive: true });

// ---------------------------------------------------------------------------
// animação visual da aeronave
// ---------------------------------------------------------------------------
function animateAircraft(dt) {
  const { ac, fm } = GAME;
  const parts = ac.parts;
  const fmLike = fm;

  ac.group.position.copy(fm.pos);
  ac.group.quaternion.copy(fm.quat);

  const rpm = fm.rpm;
  if (parts.prop) {
    parts.prop.rotation.z += rpm * 85 * dt;
    parts.blur.material.opacity = rpm * 0.28;
  }
  if (parts.fans) {
    for (const f of parts.fans) f.rotation.z += rpm * 60 * dt;
    if (parts.blurFans) for (const d of parts.blurFans) d.material.opacity = rpm * 0.3;
  }

  // superfícies de controle
  const flapAng = (input.flapsIdx / Math.max(1, ac.spec.flaps.length - 1)) * 0.62;
  if (parts.flapL) { parts.flapL.rotation.x = flapAng; parts.flapR.rotation.x = flapAng; }
  if (parts.ailL) {
    parts.ailL.rotation.x = -input.effRoll * 0.4;
    parts.ailR.rotation.x = input.effRoll * 0.4;
  }
  if (parts.elev) parts.elev.rotation.x = -input.effPitch * 0.45;
  if (parts.rudder) parts.rudder.rotation.y = -input.effYaw * 0.5;
  if (parts.spoilers) {
    const sp = fm.spoilers ? -0.95 : 0;
    for (const s of parts.spoilers) s.rotation.x += (sp - s.rotation.x) * Math.min(1, dt * 5);
  }

  // trem de pouso
  const gp = fm.gearPos;
  if (parts.gearN) parts.gearN.rotation.x = (1 - gp) * 1.5;
  if (parts.gearM) {
    parts.gearM.children.forEach((leg, i) => {
      const s = i === 0 ? -1 : 1;
      if (ac.spec.key === 'cessna') leg.rotation.z = (1 - gp) * 1.5 * s;
      else leg.rotation.z = (1 - gp) * 1.6 * s;
    });
  }
  if (parts.wheels && fm.onGround) {
    const gs = Math.hypot(fm.vel.x, fm.vel.z);
    for (const w of parts.wheels) w.rotation.x += gs * dt / 0.5;
  }

  // luzes
  const t = GAME.tSim;
  parts.beacon.visible = (t % 1.2) < 0.15;
  parts.strobeL.visible = parts.strobeR.visible = ((t % 1.6) < 0.05) || (((t + 0.12) % 1.6) < 0.05);
  const night = env.nightFactor;
  if (parts.landingLight) parts.landingLight.intensity = (night > 0.35 && fm.gearPos > 0.8) ? 55 : 0;
  if (parts.windowMat) parts.windowMat.emissiveIntensity = night * 0.9;
  if (GAME.cockpit) GAME.cockpit.light.intensity = isCockpitActive() && night > 0.2 ? 0.7 : 0;

  // manche do cockpit
  if (GAME.cockpit && GAME.cockpit.group.visible) {
    GAME.cockpit.yoke.rotation.x = input.effPitch * 0.25;
    GAME.cockpit.yoke.rotation.z = -input.effRoll * 0.6;
    GAME.cockpit.throttle.rotation.x = -0.8 - fm.throttle * 0.5;
  }
}
function isCockpitActive() { return GAME.camMode === 2; }

// ---------------------------------------------------------------------------
// avisos e HUD
// ---------------------------------------------------------------------------
function buildWarnings(fm, d, aglFt) {
  const list = [];
  if (fm.crashed) return list;
  if (fm.stalled && !fm.onGround) list.push(['stall', 'PERDA DE SUSTENTAÇÃO', '']);
  if (d.iasKt > fm.spec.vne * MS2KT * 1.02) list.push(['ovspd', 'VELOCIDADE EXCESSIVA', '']);
  if (fm.gLoad > 4.5 || fm.gLoad < -1.5) list.push(['g', 'FORÇA G EXTREMA', '']);
  if (!fm.onGround && aglFt < 130 && fm.vel.y < -6) list.push(['terr', 'TERRENO — ARREMETIDA', '']);
  if (!fm.gearDown && !fm.onGround && aglFt < 400 && fm.vel.y < -1 && d.iasKt < fm.spec.vApproach * 2.6 * MS2KT)
    list.push(['gear', 'TREM DE POUSO RECOLHIDO', '']);
  if (fm.fuel <= 0) list.push(['fuel', 'SEM COMBUSTÍVEL', '']);
  else if (fm.fuel / fm.spec.fuelCap < 0.1) list.push(['fuel', 'COMBUSTÍVEL BAIXO', 'amber']);
  if (fm.overheat) list.push(['temp', 'TEMPERATURA DO MOTOR ALTA', 'amber']);
  if (fm.onGround && fm.brakes > 0 && Math.hypot(fm.vel.x, fm.vel.z) > 1) list.push(['brk', 'FREIOS', 'green']);
  if (fm.reverse && fm.onGround) list.push(['rvs', 'REVERSO ATIVO', 'green']);
  if (fm.stalled === false && fm.alpha > (fm.spec.alphaStall - 3) * D2R && !fm.onGround && fm.vel.length() > 15)
    list.push(['pre', 'ATENÇÃO: ESTOL PRÓXIMO', 'amber']);
  return list;
}

// ---------------------------------------------------------------------------
// loop principal
// ---------------------------------------------------------------------------
const PHYS_DT = 1 / 120;
let lastT = performance.now();
let acc = 0;

function frame() {
  requestAnimationFrame(frame);
  const now = performance.now();
  let dt = Math.min(0.1, (now - lastT) / 1000);
  lastT = now;

  if (!GAME.started || GAME.paused) {
    renderer.render(scene, camera);
    return;
  }

  input.sample(dt);

  // física em passos fixos
  acc += dt;
  let steps = 0;
  while (acc >= PHYS_DT && steps < 10) {
    GAME.fm.step(PHYS_DT, {
      pitch: input.effPitch, roll: input.effRoll, yaw: input.effYaw,
      throttle: input.throttle, brakes: input.brakes,
      gearDown: input.gearDown, flapsIdx: input.flapsIdx,
      spoilers: input.spoilers, reverse: input.reverse,
    }, env, terrainHeight, GAME.tSim);
    GAME.tSim += PHYS_DT;
    acc -= PHYS_DT;
    steps++;
    if (GAME.fm.crashed) break;
  }

  const fm = GAME.fm;
  const d = fm.data(env);
  const gh = terrainHeight(fm.pos.x, fm.pos.z);
  const aglFt = (fm.pos.y - gh) * FT;

  // mensagem de toque
  if (fm.onGround && GAME.lastAGL > 2.5) {
    const fpm = Math.abs(fm.lastTouchVS * FT * 60);
    let q;
    if (fpm < 90) q = '✨ Toque perfeito!';
    else if (fpm < 300) q = '✅ Bom toque';
    else if (fpm < 600) q = '⚠️ Toque firme';
    else q = '⚠️ Toque muito forte';
    GAME.touchMsg = `${q} — ${fpm.toFixed(0)} ft/min`;
    sound.click();
  }
  GAME.lastAGL = aglFt;

  // crash
  if (fm.crashed && !$('crashOverlay').classList.contains('hidden') === false) { /* noop */ }
  if (fm.crashed && $('crashOverlay').classList.contains('hidden')) {
    $('crashReason').textContent = fm.crashReason;
    $('crashStats').textContent =
      `Velocidade: ${Math.round(d.gsKt)} kt · Distância percorrida desde a decolagem: registro do voo`;
    $('crashOverlay').classList.remove('hidden');
    $('controls').classList.add('hidden');
  }

  // atmosfera e mundo
  env.update(dt, camera.position, fm.pos);
  world.update(dt, fm.pos, env.nightFactor);
  animateAircraft(dt);
  updateCamera(dt);

  // instrumentos do cockpit
  const f = _v1.set(0, 0, 1).applyQuaternion(fm.quat);
  const r = _v2.set(1, 0, 0).applyQuaternion(fm.quat);
  instruments.update(dt, {
    pitchDeg: Math.asin(THREE.MathUtils.clamp(f.y, -1, 1)) * R2D,
    rollRad: Math.atan2(r.y, Math.hypot(r.x, r.z)),
    iasKt: d.iasKt, altFt: d.altFt,
    vneKt: fm.spec.vne * MS2KT,
  });

  // HUD
  const envWind = env._wind;
  hud.update(dt, {
    iasKt: d.iasKt, gsKt: d.gsKt,
    altFt: d.altFt, aglFt,
    hdg: d.hdg, vsFpm: d.vsFpm,
    throttle: fm.throttle,
    fuelPct: (fm.fuel / fm.spec.fuelCap) * 100,
    temp: fm.temp,
    flapName: fm.spec.flaps[fm.flapsIdx].name,
    gearTxt: fm.gearPos > 0.98 ? 'ABAIXADO' : fm.gearPos < 0.02 ? 'RECOLHIDO' : 'MOVENDO…',
    gearCol: fm.gearPos > 0.98 ? '#7cff9e' : fm.gearPos < 0.02 ? '#dfeeff' : '#ffc24d',
    mach: d.mach,
    windTxt: `${Math.round(env.windSpeed * MS2KT)}KT/${Math.round((env.windDirRad * R2D + 360) % 360)}°`,
    quality: GAME.quality,
    touchMsg: GAME.touchMsg,
  });
  GAME.touchMsg = '';
  hud.setWarnings(buildWarnings(fm, d, aglFt));

  // áudio
  const camDist = camera.position.distanceTo(fm.pos);
  _v3.copy(fm.pos).sub(camera.position).normalize();
  const camRight = _v1.set(1, 0, 0).applyQuaternion(camera.quaternion);
  sound.update(dt, {
    type: fm.spec.engine.type, rpm: fm.rpm, throttle: fm.throttle,
    airspeedMS: fm.vel.length(),
    rainAmt: env.cfg.rain > 0 ? env.rain.material.opacity : 0,
    stall: fm.stalled && !fm.onGround,
    camDist, pan: _v3.dot(camRight), cockpit: GAME.camMode === 2,
  });

  renderer.render(scene, camera);
}

// ---------------------------------------------------------------------------
// UI: overlay inicial / pausa / crash
// ---------------------------------------------------------------------------
function chipGroup(id, onPick) {
  document.querySelectorAll(`#${id} .chip`).forEach(ch => {
    ch.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      document.querySelectorAll(`#${id} .chip`).forEach(c => c.classList.remove('sel'));
      ch.classList.add('sel');
      sound.click();
      onPick(ch.dataset.v);
    });
  });
}

function buildAircraftCards() {
  const cards = $('acCards');
  cards.innerHTML = '';
  for (const key of Object.keys(SPECS)) {
    const s = SPECS[key];
    const div = document.createElement('div');
    div.className = 'acard' + (key === GAME.aircraftKey ? ' sel' : '');
    div.dataset.v = key;
    div.innerHTML = `<div class="nm">${s.name}</div><div class="tp">${s.type}</div>
      <div class="st">${s.desc}<br>Peso: ${(s.mass / 1000).toFixed(1)} t · Motores: ${s.engine.count}${s.engine.type === 'jet' ? ' × jato' : ' × hélice'}<br>
      Estol ≈ ${Math.round(stallKt(s))} kt · Rotação ≈ ${Math.round(s.vRotate * MS2KT)} kt</div>`;
    div.addEventListener('pointerdown', (e) => {
      e.preventDefault();
      cards.querySelectorAll('.acard').forEach(c => c.classList.remove('sel'));
      div.classList.add('sel');
      GAME.aircraftKey = key;
      sound.click();
    });
    cards.appendChild(div);
  }
}
function stallKt(s) {
  const clMax = s.CL0 + s.CLa * s.alphaStall * D2R + s.flaps[1] ? s.flaps[1].cl : 0;
  const cl = s.CL0 + s.CLa * s.alphaStall * D2R + (s.flaps[1] ? s.flaps[1].cl : 0);
  return Math.sqrt(2 * (s.mass + s.fuelCap * 0.5) * 9.81 / (1.225 * s.S * cl)) * MS2KT;
}

function show(id) { $(id).classList.remove('hidden'); }
function hide(id) { $(id).classList.add('hidden'); }

function startFlight() {
  sound.init(); sound.resume();
  hide('startOverlay');
  hide('loading');
  show('hud'); show('controls');
  spawnAircraft(GAME.aircraftKey);
  spawn();
  GAME.started = true;
  GAME.paused = false;
  lastT = performance.now();
}

function togglePause() {
  if (!GAME.started) return;
  GAME.paused = !GAME.paused;
  if (GAME.paused) show('pauseOverlay'); else { hide('pauseOverlay'); lastT = performance.now(); }
}

chipGroup('startChips', v => GAME.startMode = v);
chipGroup('wxChips', v => env.setWeather(v));
chipGroup('wxChips2', v => env.setWeather(v));
chipGroup('gfxChips', v => applyQuality(v));
chipGroup('gfxChips2', v => applyQuality(v));
chipGroup('timeChips', v => { env.timeOfDay = parseFloat(v); });
buildAircraftCards();

$('btnStart').addEventListener('pointerdown', (e) => { e.preventDefault(); startFlight(); });
$('btnResume').addEventListener('pointerdown', (e) => { e.preventDefault(); togglePause(); });
$('btnRestart').addEventListener('pointerdown', (e) => { e.preventDefault(); hide('pauseOverlay'); GAME.paused = false; spawn(); lastT = performance.now(); });
$('btnFlyAgain').addEventListener('pointerdown', (e) => { e.preventDefault(); hide('crashOverlay'); show('controls'); spawn(); lastT = performance.now(); });
$('btnPause').addEventListener('pointerdown', (e) => { e.preventDefault(); });

input.bind({
  joyZone: $('joyZone'), joyStick: $('joyStick'),
  thrSlider: $('thrSlider'), thrFill: $('thrFill'), thrHandle: $('thrHandle'),
  btnGear: $('btnGear'), btnFlaps: $('btnFlaps'), btnSpr: $('btnSpr'), btnRvs: $('btnRvs'),
  btnBrk: $('btnBrk'), btnRudL: $('btnRudL'), btnRudR: $('btnRudR'),
  btnCam: $('btnCam'), btnPause: $('btnPause'), btnTilt: $('btnTilt'), btnSound: $('btnSound'),
}, {
  click: () => { sound.init(); sound.click(); },
  syncGear: () => syncButtons(),
  syncFlaps: () => syncButtons(),
  syncSpr: () => syncButtons(),
  syncRvs: () => syncButtons(),
  syncBrk: () => syncButtons(),
  camera: () => {
    GAME.camMode = (GAME.camMode + 1) % 4;
    if (GAME.camMode === 0) orbitBehind();
    hud.setCam(GAME.camNames[GAME.camMode]);
    _chaseInit = false;
  },
  pause: () => togglePause(),
  tilt: () => {
    const go = async () => {
      const on = input.toggleTilt();
      $('btnTilt').style.background = on ? 'rgba(57,210,255,.4)' : '';
    };
    if (typeof DeviceOrientationEvent !== 'undefined' && DeviceOrientationEvent.requestPermission) {
      DeviceOrientationEvent.requestPermission().then(() => go()).catch(() => { });
    } else go();
  },
  sound: () => {
    sound.init();
    sound.setEnabled(!sound.enabled);
    $('btnSound').textContent = sound.enabled ? '🔊' : '🔇';
  },
});

window.addEventListener('resize', () => {
  camera.aspect = innerWidth / innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(innerWidth, innerHeight);
});

// ---------------------------------------------------------------------------
// API de depuração/teste
// ---------------------------------------------------------------------------
window.SIM = {
  get state() {
    const fm = GAME.fm;
    if (!fm) return null;
    const d = fm.data(env);
    const gh = terrainHeight(fm.pos.x, fm.pos.z);
    return {
      pos: fm.pos.toArray(), vel: fm.vel.toArray(),
      iasKt: d.iasKt, gsKt: d.gsKt, altFt: d.altFt, aglFt: (fm.pos.y - gh) * FT,
      hdg: d.hdg, alphaDeg: d.alphaDeg, onGround: fm.onGround, crashed: fm.crashed,
      rpm: fm.rpm, fuel: fm.fuel, throttle: fm.throttle, gearPos: fm.gearPos,
      stalled: fm.stalled, gLoad: fm.gLoad, vsFpm: d.vsFpm,
      started: GAME.started, paused: GAME.paused, craft: GAME.aircraftKey,
      camMode: GAME.camMode, timeOfDay: env.timeOfDay,
    };
  },
  step(n) {
    for (let i = 0; i < n; i++) {
      GAME.fm.step(PHYS_DT, {
        pitch: input.effPitch, roll: input.effRoll, yaw: input.effYaw,
        throttle: input.throttle, brakes: input.brakes,
        gearDown: input.gearDown, flapsIdx: input.flapsIdx,
        spoilers: input.spoilers, reverse: input.reverse,
      }, env, terrainHeight, GAME.tSim);
      GAME.tSim += PHYS_DT;
      if (GAME.fm.crashed) break;
    }
    return this.state;
  },
  setInput(o) { Object.assign(input, o); },
  tp(x, y, z, hdg = 90, speed = 0) {
    GAME.fm.reset(new THREE.Vector3(x, y, z), hdg, speed, speed > 0 ? 1 : 0);
  },
  setTime(h) { env.timeOfDay = h; },
  setWeather(k) { env.setWeather(k); },
  setQuality(k) { applyQuality(k); },
  cam(m) { GAME.camMode = m; _chaseInit = false; },
  errors: window.__errors,
};

// ---------------------------------------------------------------------------
// pré-construção do terreno próximo do aeroporto + primeira renderização
// ---------------------------------------------------------------------------
applyQuality(GAME.quality);
for (let i = 0; i < 200 && world.terrain.update(0, 0) > 0; i++) { /* constrói chunks */ }
env.update(0.016, new THREE.Vector3(0, 12, 0), new THREE.Vector3(0, 8, 0));
world.update(0.016, new THREE.Vector3(0, 8, 0), 0);
renderer.render(scene, camera);
hide('loading');
frame();

