335:     parts.ailR.rotation.x = input.effRoll * 0.4;
336:   }
337:   if (parts.elev) parts.elev.rotation.x = -input.effPitch * 0.45;
338:   if (parts.rudder) parts.rudder.rotation.y = -input.effYaw * 0.5;
339:   if (parts.spoilers) {
340:     const sp = fm.spoilers ? -0.95 : 0;
341:     for (const s of parts.spoilers) s.rotation.x += (sp - s.rotation.x) * Math.min(1, dt * 5);
342:   }
343: 
344:   // trem de pouso
345:   const gp = fm.gearPos;
346:   if (parts.gearN) parts.gearN.rotation.x = (1 - gp) * 1.5;
347:   if (parts.gearM) {
348:     parts.gearM.children.forEach((leg, i) => {
349:       const s = i === 0 ? -1 : 1;
350:       if (ac.spec.key === 'cessna') leg.rotation.z = (1 - gp) * 1.5 * s;
351:       else leg.rotation.z = (1 - gp) * 1.6 * s;
352:     });
353:   }
354:   if (parts.wheels && fm.onGround) {
355:     const gs = Math.hypot(fm.vel.x, fm.vel.z);
356:     for (const w of parts.wheels) w.rotation.x += gs * dt / 0.5;
357:   }
358: 
359:   // luzes
360:   const t = GAME.tSim;
361:   parts.beacon.visible = (t % 1.2) < 0.15;
362:   parts.strobeL.visible = parts.strobeR.visible = ((t % 1.6) < 0.05) || (((t + 0.12) % 1.6) < 0.05);
363:   const night = env.nightFactor;
364:   if (parts.landingLight) parts.landingLight.intensity = (night > 0.35 && fm.gearPos > 0.8) ? 55 : 0;
365:   if (parts.windowMat) parts.windowMat.emissiveIntensity = night * 0.9;
366:   if (GAME.cockpit) GAME.cockpit.light.intensity = isCockpitActive() ? (night > 0.2 ? 0.9 : 1.4) : 0;
367: 
368:   // manche do cockpit
369:   if (GAME.cockpit && GAME.cockpit.group.visible) {
370:     GAME.cockpit.yoke.rotation.x = input.effPitch * 0.25;
371:     GAME.cockpit.yoke.rotation.z = -input.effRoll * 0.6;
372:     GAME.cockpit.throttle.rotation.x = -0.8 - fm.throttle * 0.5;
