96: class Gauge {
97:   constructor(size, draw) {
98:     this.canvas = document.createElement('canvas');
99:     this.canvas.width = size; this.canvas.height = size;
100:     this.ctx = this.canvas.getContext('2d');
101:     this.texture = new THREE.CanvasTexture(this.canvas);
102:     this.texture.colorSpace = THREE.SRGBColorSpace;
103:     this.draw = draw;
104:     this.size = size;
105:     this._t = 0;
106:   }
107:   update(state) {
108:     this.ctx.clearRect(0, 0, this.size, this.size);
109:     this.draw(this.ctx, this.size, state);
110:     this.texture.needsUpdate = true;
111:   }
112: }
