114: function dialBase(g, s, label) {
115:   g.fillStyle = '#0a0e14'; g.fillRect(0, 0, s, s);
116:   g.fillStyle = '#101820'; g.beginPath(); g.arc(s / 2, s / 2, s * 0.46, 0, Math.PI * 2); g.fill();
117:   g.strokeStyle = '#2a3a4c'; g.lineWidth = s * 0.02;
118:   g.beginPath(); g.arc(s / 2, s / 2, s * 0.46, 0, Math.PI * 2); g.stroke();
119:   g.fillStyle = '#8fb4d6'; g.font = `${s * 0.09}px Arial`; g.textAlign = 'center';
120:   g.fillText(label, s / 2, s * 0.78);
121: }
122: function needle(g, s, ang, len, color, w) {
123:   g.save(); g.translate(s / 2, s / 2); g.rotate(ang);
124:   g.strokeStyle = color; g.lineWidth = w || s * 0.02;
125:   g.beginPath(); g.moveTo(0, s * 0.08); g.lineTo(0, -s * len); g.stroke();
126:   g.restore();
127: }
128: const TAU = Math.PI * 2;
129: 
130: export class CockpitInstruments {
131:   constructor() {
132:     // indicador de atitude
133:     this.att = new Gauge(256, (g, s, st) => {
134:       g.save();
135:       g.beginPath(); g.arc(s / 2, s / 2, s * 0.46, 0, TAU); g.clip();
136:       const pitchPx = THREE.MathUtils.clamp(st.pitchDeg / 40, -1.2, 1.2) * s * 0.42;
137:       const rollRad = -st.rollRad;
138:       g.save(); g.translate(s / 2, s / 2); g.rotate(rollRad); g.translate(0, pitchPx);
139:       g.fillStyle = '#2f7fd4'; g.fillRect(-s, -s * 1.6, s * 2, s * 1.6);
140:       g.fillStyle = '#7a4d2a'; g.fillRect(-s, 0, s * 2, s * 1.6);
141:       g.strokeStyle = '#fff'; g.lineWidth = 2;
142:       g.beginPath(); g.moveTo(-s, 0); g.lineTo(s, 0); g.stroke();
143:       for (const d of [-20, -10, 10, 20]) {
144:         const y = -d / 40 * s * 0.42;
145:         g.beginPath(); g.moveTo(-s * 0.14, y); g.lineTo(s * 0.14, y); g.stroke();
146:       }
147:       g.restore();
148:       // marca fixa da aeronave
149:       g.strokeStyle = '#ffcf3d'; g.lineWidth = s * 0.025;
150:       g.beginPath(); g.moveTo(s * 0.2, s / 2); g.lineTo(s * 0.38, s / 2); g.lineTo(s * 0.44, s / 2 + s * 0.05);
151:       g.moveTo(s * 0.8 - s * 0.2, s / 2); g.lineTo(s * (1 - 0.38), s / 2); g.lineTo(s * (1 - 0.44), s / 2 + s * 0.05);
152:       g.stroke();
153:       g.restore();
154:       g.strokeStyle = '#2a3a4c'; g.lineWidth = s * 0.02;
155:       g.beginPath(); g.arc(s / 2, s / 2, s * 0.46, 0, TAU); g.stroke();
156:     });
157:     // velocidade
158:     this.asi = new Gauge(256, (g, s, st) => {
159:       dialBase(g, s, 'KT');
160:       for (let v = 0; v <= 200; v += 20) {
161:         const a = -Math.PI * 1.25 + (v / 200) * TAU * 0.75;
162:         g.save(); g.translate(s / 2, s / 2); g.rotate(a);
163:         g.strokeStyle = v >= st.vneKt ? '#ff5050' : '#cfe4f7'; g.lineWidth = s * 0.012;
164:         g.beginPath(); g.moveTo(0, -s * 0.38); g.lineTo(0, -s * 0.44); g.stroke();
165:         if (v % 40 === 0) {
166:           g.fillStyle = '#cfe4f7'; g.font = `${s * 0.1}px Arial`; g.textAlign = 'center';
167:           g.fillText(v, Math.sin(a) * s * 0.3, -Math.cos(a) * s * 0.3 + s * 0.035);
168:         }
169:         g.restore();
170:       }
171:       needle(g, s, -Math.PI * 1.25 + THREE.MathUtils.clamp(st.iasKt / 200, 0, 1) * TAU * 0.75, 0.36, '#ff5a3c');
172:       g.fillStyle = '#fff'; g.beginPath(); g.arc(s / 2, s / 2, s * 0.03, 0, TAU); g.fill();
173:     });
174:     // altímetro
175:     this.alt = new Gauge(256, (g, s, st) => {
176:       dialBase(g, s, 'FT x100');
177:       for (let v = 0; v < 10; v++) {
178:         const a = (v / 10) * TAU;
179:         g.save(); g.translate(s / 2, s / 2); g.rotate(a);
180:         g.strokeStyle = '#cfe4f7'; g.lineWidth = s * 0.012;
181:         g.beginPath(); g.moveTo(0, -s * 0.38); g.lineTo(0, -s * 0.44); g.stroke();
182:         g.restore();
183:       }
184:       needle(g, s, (st.altFt % 10000) / 10000 * TAU, 0.34, '#fff');
185:       needle(g, s, (st.altFt / 100000) * TAU, 0.2, '#8fb4d6', s * 0.03);
186:       g.fillStyle = '#fff'; g.beginPath(); g.arc(s / 2, s / 2, s * 0.03, 0, TAU); g.fill();
187:     });
188:     this.gauges = [this.att, this.asi, this.alt];
189:     this._acc = 0;
190:   }
191:   update(dt, state) {
192:     this._acc += dt;
193:     if (this._acc < 0.1) return;   // 10 Hz
194:     this._acc = 0;
195:     this.att.update(state); this.asi.update(state); this.alt.update(state);
196:   }
197: }
