200: function makeWheel(r, w) {
201:   const g = new THREE.Group();
202:   const tire = new THREE.Mesh(new THREE.CylinderGeometry(r, r, w, 12), matTire());
203:   tire.rotation.z = Math.PI / 2;
204:   const hub = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.45, r * 0.45, w * 1.05, 8), matMetal());
205:   hub.rotation.z = Math.PI / 2;
206:   g.add(tire, hub);
207:   g.userData.r = r;
208:   return g;
209: }
