212: function surface(wingSpan, chord, thick, material) {
213:   const pivot = new THREE.Group();
214:   const m = new THREE.Mesh(new THREE.BoxGeometry(wingSpan, thick, chord), material);
215:   m.position.z = chord / 2;
216:   pivot.add(m);
217:   return pivot;
218: }
