263:   // flaps + ailerons (articulados)
264:   parts.flapL = surface(2.6, 0.5, 0.09, accent); parts.flapL.position.set(-1.9, 0.95, -0.05);
265:   parts.flapR = surface(2.6, 0.5, 0.09, accent); parts.flapR.position.set(1.9, 0.95, -0.05);
