267:   parts.ailR = surface(2.4, 0.42, 0.08, accent); parts.ailR.position.set(4.2, 0.95, -0.02);
268:   grp.add(parts.flapL, parts.flapR, parts.ailL, parts.ailR);
269: 
270:   // empenagem
271:   const hStab = new THREE.Mesh(new THREE.BoxGeometry(3.4, 0.1, 1.0), wingMat);
272:   hStab.position.set(0, 0.18, -4.1);
273:   const fin = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.5, 1.1), wingMat);
274:   fin.position.set(0, 0.85, -4.2);
275:   grp.add(hStab, fin);
276:   const finTip = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.5, 1.1), accent);
277:   finTip.position.set(0, 1.7, -4.2);
278:   grp.add(finTip);
279: 
280:   parts.elev = surface(3.3, 0.4, 0.07, accent); parts.elev.position.set(0, 0.18, -4.65);
281:   parts.rudder = surface(1.0, 0.5, 0.07, accent);
282:   parts.rudder.rotation.y = Math.PI / 2;
283:   parts.rudder.position.set(0, 0.85, -4.75);
284:   // rudder pivot: caixa vertical
285:   parts.rudder.children[0].geometry = new THREE.BoxGeometry(0.09, 1.3, 0.5);
286:   parts.rudder.children[0].position.set(0, 0, 0.25);
287:   grp.add(parts.elev, parts.rudder);
288: 
289:   // hélice
290:   const propG = new THREE.Group();
291:   const spinner = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.55, 10), matMetal());
292:   spinner.rotation.x = Math.PI / 2; spinner.position.z = 0.25;
293:   const blade1 = new THREE.Mesh(new THREE.BoxGeometry(0.16, 1.9, 0.05), matDark());
294:   const blade2 = blade1.clone(); blade2.rotation.z = Math.PI / 2;
295:   propG.add(spinner, blade1, blade2);
296:   propG.position.z = 4.35;
297:   parts.prop = propG;
298:   grp.add(propG);
299: 
300:   // trem de pouso retrátil
301:   parts.gear = new THREE.Group();
302:   const mkLeg = (x, z, len, wheelR) => {
303:     const lg = new THREE.Group();
304:     const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, len, 6), matMetal());
