308:     lg.add(leg, wheel);
309:     lg.position.set(x, 0, z);
310:     lg.userData.wheel = wheel;
311:     return lg;
312:   };
313:   parts.gearN = mkLeg(0, 2.4, 0.62, 0.24);
314:   parts.gearM = new THREE.Group();
315:   const mLegL = mkLeg(-1.35, 0.35, 0.55, 0.27);
316:   const mLegR = mkLeg(1.35, 0.35, 0.55, 0.27);
