318:   parts.gear.add(parts.gearN, parts.gearM);
319:   parts.gear.position.y = 0.0;
320:   grp.add(parts.gear);
321:   parts.wheels = [parts.gearN.userData.wheel, mLegL.userData.wheel, mLegR.userData.wheel];
322: 
323:   // luzes
324:   parts.navL = new THREE.Mesh(new THREE.SphereGeometry(0.07, 6, 4), new THREE.MeshBasicMaterial({ color: 0xff2020 }));
325:   parts.navL.position.set(-5.8, 0.95, 0.75);
326:   parts.navR = new THREE.Mesh(new THREE.SphereGeometry(0.07, 6, 4), new THREE.MeshBasicMaterial({ color: 0x20ff40 }));
327:   parts.navR.position.set(5.8, 0.95, 0.75);
328:   parts.beacon = new THREE.Mesh(new THREE.SphereGeometry(0.07, 6, 4), new THREE.MeshBasicMaterial({ color: 0xff2020 }));
329:   parts.beacon.position.set(0, 1.85, -0.5);
330:   parts.strobeL = new THREE.Mesh(new THREE.SphereGeometry(0.06, 6, 4), new THREE.MeshBasicMaterial({ color: 0xffffff }));
331:   parts.strobeL.position.copy(parts.navL.position);
332:   parts.strobeR = parts.strobeL.clone(); parts.strobeR.position.copy(parts.navR.position);
333:   grp.add(parts.navL, parts.navR, parts.beacon, parts.strobeL, parts.strobeR);
334: 
335:   grp.traverse(o => { if (o.isMesh && o.material !== matTire()) { o.castShadow = true; } });
336:   return { grp, parts };
337: }
